import { expect, test } from "@playwright/test";

import { openStudio, resetRepository } from "./helpers";

/**
 * The Opportunity Landscape is where scored outcomes are read. These tests
 * cover the parts a user relies on: the headline numbers, the score pills on
 * each card, and the filter that narrows the view to what is underserved.
 */

/** A job with two outcomes: one underserved, one appropriately served. */
async function seedOutcomes(
  page: import("@playwright/test").Page,
  request: import("@playwright/test").APIRequestContext,
): Promise<void> {
  const job = await request.post("/api/jobs", {
    data: { name: "Deploy a service safely", description: "Platform engineers", mcp_url: "" },
  });
  expect(job.ok()).toBeTruthy();
  const { result } = (await job.json()) as { result: { id: string } };

  for (const outcome of [
    { statement: "Minimize the time to deploy a service", importance: 9.2, satisfaction: 3.1 },
    { statement: "Minimize the effort to rotate expired tokens", importance: 8.0, satisfaction: 7.2 },
  ]) {
    const created = await request.post("/api/outcomes", {
      data: { mcp_url: "", job_id: result.id, ...outcome },
    });
    expect(created.ok()).toBeTruthy();
  }

  await openStudio(page);
}

test.describe("the opportunity landscape", () => {
  test.beforeEach(async ({ request }) => {
    await resetRepository(request);
  });

  test("reports the number of jobs and outcomes", async ({ page, request }) => {
    await seedOutcomes(page, request);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();
    const landscape = page.getByRole("complementary", { name: "Opportunity landscape" });
    await expect(landscape).toBeVisible();

    await expect(landscape.getByText("Active Job Map Contexts")).toBeVisible();
    await expect(landscape.getByText("Underserved Targets (>10)")).toBeVisible();
    await expect(landscape.getByText("Total Opportunities Analyzed")).toBeVisible();
  });

  test("labels an underserved outcome and a served one", async ({ page, request }) => {
    await seedOutcomes(page, request);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();
    const landscape = page.getByRole("complementary", { name: "Opportunity landscape" });

    // 9.2 + max(9.2 - 3.1, 0) = 15.30, which is underserved.
    await expect(landscape.getByText("🔥 Underserved (Opp: 15.3)")).toBeVisible();
    // 8.0 + max(8.0 - 7.2, 0) = 8.80, which is not.
    await expect(landscape.getByText("✓ Served (Opp: 8.8)")).toBeVisible();
  });

  test("filters to underserved outcomes only", async ({ page, request }) => {
    await seedOutcomes(page, request);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();
    const landscape = page.getByRole("complementary", { name: "Opportunity landscape" });

    // The table view lists each outcome by statement.
    await landscape.getByRole("button", { name: "📋 Table View" }).click();
    await expect(landscape.getByText("Minimize the time to deploy a service")).toBeVisible();
    await expect(landscape.getByText("Minimize the effort to rotate expired tokens")).toBeVisible();

    await landscape.getByLabel("Show Underserved Only (>10)").check();

    await expect(landscape.getByText("Minimize the time to deploy a service")).toBeVisible();
    await expect(landscape.getByText("Minimize the effort to rotate expired tokens")).toBeHidden();
  });

  test("switches between the matrix, card, and table views", async ({ page, request }) => {
    await seedOutcomes(page, request);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();
    const landscape = page.getByRole("complementary", { name: "Opportunity landscape" });

    await expect(landscape.getByRole("button", { name: "📊 Matrix" })).toBeVisible();

    await landscape.getByRole("button", { name: "🎴 Visual Cards" }).click();
    await expect(landscape.getByRole("button", { name: "🎴 Visual Cards" })).toBeVisible();

    await landscape.getByRole("button", { name: "📋 Table View" }).click();
    await expect(landscape.getByRole("columnheader", { name: "Opp. Score" })).toBeVisible();
  });
});

import { expect, test } from "@playwright/test";

import { lens, openStudio, rail, resetRepository } from "./helpers";

/**
 * The Studio is a single surface with views that open beside the
 * conversation. These tests cover opening a view, that it is announced
 * correctly to assistive technology, and that it closes again.
 */
test.describe("the workspace", () => {
  test.beforeEach(async ({ request }) => {
    await resetRepository(request);
  });

  test("opens the opportunity landscape from the rail", async ({ page }) => {
    await openStudio(page);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();

    await expect(lens(page)).toHaveAttribute("aria-label", "Opportunity landscape");
  });

  test("marks the open view as current", async ({ page }) => {
    await openStudio(page);

    const landscape = page.getByRole("button", { name: "Opportunity landscape" });
    await expect(landscape).not.toHaveAttribute("aria-current", "page");

    await landscape.click();
    await expect(landscape).toHaveAttribute("aria-current", "page");
  });

  test("closes the open view", async ({ page }) => {
    await openStudio(page);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();
    await expect(lens(page)).toBeVisible();

    await page.getByRole("button", { name: "Close workspace view" }).click();
    await expect(lens(page)).toBeHidden();
  });

  test("closes the open view with Escape", async ({ page }) => {
    await openStudio(page);

    await page.getByRole("button", { name: "Opportunity landscape" }).click();
    await expect(lens(page)).toBeVisible();

    await page.keyboard.press("Escape");
    await expect(lens(page)).toBeHidden();
  });

  test("offers a way into the settings", async ({ page }) => {
    await openStudio(page);

    await page.getByRole("button", { name: "Open settings" }).click();

    await expect(lens(page)).toHaveAttribute("aria-label", "Settings");
    await expect(lens(page).getByLabel("MCP server URL")).toBeVisible();
  });

  test("shows the studio's own health in the top bar", async ({ page }) => {
    await openStudio(page);

    // No model is reachable during the test run, so the bar says so.
    await expect(page.getByRole("button", { name: "Local mode" })).toBeVisible();
  });
});

